using WAID.Application.Services;using WAID.Infrastructure.Persistence;namespace WAID.Infrastructure.Tests;public sealed class DigitalTwinPersistenceTests{[Fact]public async Task Compressed_snapshots_round_trip_and_retention_preserves_pinned(){var path=Path.Combine(Path.GetTempPath(),$"waid-twin-{Guid.NewGuid():N}.db");try{var db=new WaidDatabase($"Data Source={path};Pooling=False");await db.InitializeAsync(CancellationToken.None);var repo=new SqliteDigitalTwinRepository(db);var service=new DigitalTwinService([new Provider()],repo,TimeProvider.System);var old=await service.CaptureAsync(SystemSnapshotPurpose.Manual,false,null,null,CancellationToken.None);var pinned=await service.CaptureAsync(SystemSnapshotPurpose.Baseline,true,null,null,CancellationToken.None);await using(var c=db.OpenConnection()){await using var q=c.CreateCommand();q.CommandText="UPDATE digital_twin_snapshots SET captured_utc='2020-01-01T00:00:00Z'";await q.ExecuteNonQueryAsync();await using var size=c.CreateCommand();size.CommandText="SELECT MIN(length(compressed_payload)) FROM digital_twin_snapshots";Assert.True(Convert.ToInt32(await size.ExecuteScalarAsync())>0);}var result=await repo.ApplyRetentionAsync(DateTimeOffset.UtcNow.AddDays(-1),CancellationToken.None);Assert.Equal(1,result.DeletedSnapshots);Assert.Equal(pinned.Id,Assert.Single(await repo.GetRecentAsync(10,CancellationToken.None)).Id);Assert.Null(await repo.GetAsync(old.Id,CancellationToken.None));}finally{Microsoft.Data.Sqlite.SqliteConnection.ClearAllPools();if(File.Exists(path))File.Delete(path);}}private sealed class Provider:ISystemSnapshotComponentProvider{public string Name=>"os";public string SerializerVersion=>"1";public Task<IReadOnlyDictionary<string,string>>CaptureAsync(CancellationToken t)=>Task.FromResult<IReadOnlyDictionary<string,string>>(new Dictionary<string,string>{{"version","1"}});}}
